using System.Collections.Concurrent;
using System.Text.Json;

namespace CombatSolver;

internal static class TaskTranspositionActionObservation
{
    private sealed class Counts
    {
        internal long Accepted, Potential, StrictLoss, StrictScore, EqualLossScore;
        internal readonly ConcurrentDictionary<string, long> Deltas = new();
        internal readonly ConcurrentQueue<object> Samples = new();
    }
    private static readonly ConcurrentDictionary<string, Counts> Items = new();

    internal static void RecordNoPotential(string stage)
        => Interlocked.Increment(ref Items.GetOrAdd(stage, _ => new()).Accepted);

    internal static void Record(string stage,
        int lp, int lc, int ls, int lh, int la, double lq,
        int rp, int rc, int rs, int rh, int ra, double rq)
    {
        var c = Items.GetOrAdd(stage, _ => new());
        Interlocked.Increment(ref c.Accepted);
        long count = Interlocked.Increment(ref c.Potential);
        if (lh < rh) Interlocked.Increment(ref c.StrictLoss);
        if (lq > rq) Interlocked.Increment(ref c.StrictScore);
        if (lh == rh && lq == rq) Interlocked.Increment(ref c.EqualLossScore);
        string key = $"lossSaving={rh-lh}/extraActions={la-ra}/strictScore={lq>rq}";
        c.Deltas.AddOrUpdate(key, 1, (_, old) => old + 1);
        if (count <= 12) c.Samples.Enqueue(new {
            current = new { potions=lp, cost=lc, sold=ls, lost=lh, actions=la, score=lq },
            next = new { potions=rp, cost=rc, sold=rs, lost=rh, actions=ra, score=rq }
        });
    }

    internal static string Snapshot() => JsonSerializer.Serialize(Items.OrderBy(p => p.Key).Select(p => new {
        stage=p.Key, sameStateAccepted=p.Value.Accepted, potentialActionOnly=p.Value.Potential,
        strictLoss=p.Value.StrictLoss, strictScore=p.Value.StrictScore,
        equalLossAndScore=p.Value.EqualLossScore, deltas=p.Value.Deltas, samples=p.Value.Samples.ToArray()
    }).ToArray());
}

