using System.Runtime.CompilerServices;

namespace CombatSolver;

internal sealed partial class CombatBeamSolver
{
    private readonly record struct TranspositionLabel(
        int PotionCount,
        int PotionStrategicCost,
        int FutureSoldHp,
        int CumulativePlayerHpLost,
        int ActionCount,
        double Score);

    private struct TranspositionFrontier(TranspositionLabel first)
    {
        // Table cells hold the common singleton inline. An antichain still owns
        // its original mutable list; callers mutate cells through refs only.
        private TranspositionLabel _single = first;
        private List<TranspositionLabel>? _labels;

        public int LabelCount => _labels?.Count ?? 1;

        public bool TryAccept(TranspositionLabel next)
        {
            if (_labels == null)
            {
                if (Dominates(_single, next))
                    return false;
                if (Dominates(next, _single))
                    _single = next;
                else
                    _labels = [_single, next];
                return true;
            }
            foreach (TranspositionLabel current in _labels)
            {
                if (Dominates(current, next))
                    return false;
            }
            _labels.RemoveAll(current => Dominates(next, current));
            _labels.Add(next);
            if (_labels.Count == 1)
            {
                _single = next;
                _labels = null;
            }
            return true;
        }

        private static bool Dominates(TranspositionLabel left, TranspositionLabel right)
            => left.PotionCount <= right.PotionCount
                && left.PotionStrategicCost <= right.PotionStrategicCost
                && left.FutureSoldHp <= right.FutureSoldHp
                && left.CumulativePlayerHpLost <= right.CumulativePlayerHpLost
                && left.ActionCount <= right.ActionCount
                && left.Score >= right.Score;
    }

    // Private to a solver run, just like the prior dictionaries. A compact index
    // avoids retaining one object per state. Fixed blocks also avoid copying all
    // label values into discarded dictionary arrays during No-GC growth.
    private sealed class TranspositionTable
    {
        private const int BlockShift = 10;
        private const int BlockSize = 1 << BlockShift;
        private const int BlockMask = BlockSize - 1;
        private readonly Dictionary<StateFingerprint, int> _indices = [];
        private readonly List<TranspositionFrontier[]> _blocks = [];

        public int Count => _indices.Count;

        public IEnumerable<TranspositionFrontier> Values
        {
            get
            {
                for (int index = 0; index < Count; index++)
                    yield return _blocks[index >> BlockShift][index & BlockMask];
            }
        }

        public ref TranspositionFrontier GetValueRefOrNullRef(StateFingerprint key)
        {
            if (!_indices.TryGetValue(key, out int index))
                return ref Unsafe.NullRef<TranspositionFrontier>();
            return ref _blocks[index >> BlockShift][index & BlockMask];
        }

        public void Add(StateFingerprint key, TranspositionFrontier value)
        {
            int index = Count;
            if ((index >> BlockShift) == _blocks.Count)
                _blocks.Add(new TranspositionFrontier[BlockSize]);
            _blocks[index >> BlockShift][index & BlockMask] = value;
            _indices.Add(key, index);
        }

        public TranspositionFrontier this[StateFingerprint key]
        {
            set
            {
                ref TranspositionFrontier existing = ref GetValueRefOrNullRef(key);
                if (Unsafe.IsNullRef(ref existing)) Add(key, value);
                else existing = value;
            }
        }
    }

}

