using System.Runtime.CompilerServices;

namespace CombatSolver;

internal sealed partial class CombatBeamSolver
{
    private static int _checks;

    public static void Main()
    {
        // Fixed seed; include partial-order antichains, duplicates, replacement and
        // IEEE edge values. Compare each decision to the frozen List implementation.
        Random random = new(64937);
        for (int sequence = 0; sequence < 8000; sequence++)
        {
            TranspositionLabel first = Next(random);
            TranspositionFrontier actual = new(first);
            Baseline expected = new(first);
            for (int step = 0; step < 64; step++)
            {
                TranspositionLabel next = step % 8 == 0 ? first : Next(random);
                Require(actual.TryAccept(next) == expected.TryAccept(next), "Decision differs from the old frontier.");
                Require(actual.LabelCount == expected.LabelCount, "Label count differs from the old frontier.");
            }
        }
        TranspositionLabel middle = new(3, 3, 3, 3, 3, 3);
        TranspositionFrontier changing = new(middle);
        Require(changing.TryAccept(middle with { PotionCount = 2, Score = 2 }), "Tradeoff rejected.");
        Require(changing.TryAccept(new(0, 0, 0, 0, 0, 10)), "Dominating collapse rejected.");
        Require(!changing.TryAccept(middle), "Dominated label survived collapse.");
        Require(changing.TryAccept(new(1, 0, 0, 0, 0, 11)), "Expansion after collapse rejected.");

        TranspositionCapDiagnostics diagnostics = new();
        diagnostics.ObserveEntries(1, 2, 7);
        var beforeCap = diagnostics.Capture(2, 7, 0, [1]);
        Require(!beforeCap.ReachedCap && beforeCap.FirstCapExpanded == null, "Premature cap observation.");
        diagnostics.ObserveEntries(2, 2, 11);
        diagnostics.ObserveEntries(2, 2, 19);
        var atCap = diagnostics.Capture(2, 19, 4, [1, 3]);
        Require(atCap.ReachedCap && atCap.FirstCapExpanded == 11 && atCap.LimitBypasses == 4, "First cap or bypass count lost.");
        Require(atCap.TotalLabels == 4 && atCap.LabelsPerEntry[1] == 1 && atCap.LabelsPerEntry[3] == 1, "Label distribution differs.");
        diagnostics.ObserveEntries(1, 2, 25);
        var rebuilt = diagnostics.Capture(2, 25, 4, [2]);
        Require(rebuilt.PeakEntries == 2 && rebuilt.CurrentEntries == 1 && rebuilt.FirstCapExpanded == 11, "Rebuild erased cap evidence.");
        TranspositionCapDiagnostics unlimited = new();
        unlimited.ObserveEntries(8, 0, 9);
        Require(!unlimited.Capture(0, 9, 0, [1, 1, 2]).ReachedCap, "Unlimited table reported a cap.");

        VerifyTableStorage(random, middle);
        _ = AllocateTable(1000, middle, baseline: true);
        _ = AllocateTable(1000, middle, baseline: false);
        const int count = 100_000;
        long baselineBytes = AllocateTable(count, middle, baseline: true);
        long candidateBytes = AllocateTable(count, middle, baseline: false);
        Require(candidateBytes < baselineBytes, "Chunked table did not reduce allocation from the current object frontier.");
        Console.WriteLine($"Passed {_checks} frontier/table checks; {count} retained singleton table allocations: {baselineBytes} -> {candidateBytes} bytes.");
    }

    private static void VerifyTableStorage(Random random, TranspositionLabel first)
    {
        TranspositionTable table = new();
        const int keys = 8193;
        Baseline[] expected = new Baseline[keys];
        for (int index = 0; index < keys; index++)
        {
            table.Add(new((ulong)index, (ulong)(index * 37)), new(first));
            expected[index] = new(first);
        }
        Require(table.Count == keys, "Block or dictionary growth lost an entry.");
        ref TranspositionFrontier held = ref table.GetValueRefOrNullRef(new(1023, 1023 * 37));
        for (int index = keys; index < keys + 20000; index++)
            table.Add(new((ulong)index, (ulong)(index * 37)), new(first));
        Require(held.TryAccept(first with { Score = 30 }) == expected[1023].TryAccept(first with { Score = 30 }),
            "An owned cell ref stopped referring to the original entry after growth.");
        for (int step = 0; step < 131072; step++)
        {
            int index = random.Next(keys);
            TranspositionLabel next = step % 8 == 0 ? first : Next(random);
            ref TranspositionFrontier actual = ref table.GetValueRefOrNullRef(new((ulong)index, (ulong)(index * 37)));
            Require(!Unsafe.IsNullRef(ref actual), "Existing key lookup returned a null ref.");
            Require(actual.TryAccept(next) == expected[index].TryAccept(next), "Stored cell decision differs from the frozen algorithm.");
            Require(actual.LabelCount == expected[index].LabelCount, "Mutation was made to a temporary cell copy.");
        }
        Require(Unsafe.IsNullRef(ref table.GetValueRefOrNullRef(new(ulong.MaxValue, 0))), "Missing key produced a default label.");
        int oldCount = table.Count;
        table[new(1024, 1024 * 37)] = new(first);
        Require(table.Count == oldCount && table.GetValueRefOrNullRef(new(1024, 1024 * 37)).LabelCount == 1,
            "Setup-root replacement changed the entry count or retained an old antichain.");
        table[new(ulong.MaxValue, 0)] = new(first);
        Require(table.Count == oldCount + 1 && table.Values.Count() == table.Count,
            "Rebuild assignment or diagnostic enumeration lost entries.");
        bool duplicateRejected = false;
        try { table.Add(new(1024, 1024 * 37), new(first)); }
        catch (ArgumentException) { duplicateRejected = true; }
        Require(duplicateRejected && table.Count == oldCount + 1, "Duplicate insertion changed dictionary behavior.");
        TranspositionTable independent = new();
        independent.Add(new(1023, 1023 * 37), new(first));
        Require(independent.GetValueRefOrNullRef(new(1023, 1023 * 37)).TryAccept(first with { Score = 30 }),
            "Independent solver tables shared a mutable frontier.");
        table = new();
        table.Add(new(1023, 1023 * 37), new(first));
        Require(table.GetValueRefOrNullRef(new(1023, 1023 * 37)).TryAccept(first with { Score = 30 }),
            "Cache rebuilding shared the old table's frontier.");
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private static long AllocateTable(int count, TranspositionLabel label, bool baseline)
    {
        long start = GC.GetAllocatedBytesForCurrentThread();
        if (baseline)
        {
            Dictionary<StateFingerprint, LegacyFrontier> retained = [];
            for (int i = 0; i < count; i++) retained.Add(new((ulong)i, 0), new(label));
            GC.KeepAlive(retained);
        }
        else
        {
            TranspositionTable retained = new();
            for (int i = 0; i < count; i++) retained.Add(new((ulong)i, 0), new(label));
            GC.KeepAlive(retained);
        }
        return GC.GetAllocatedBytesForCurrentThread() - start;
    }

    private static TranspositionLabel Next(Random random)
    {
        double score = random.Next(0, 80) switch
        {
            0 => double.NaN,
            1 => double.PositiveInfinity,
            2 => double.NegativeInfinity,
            _ => random.Next(-8, 9),
        };
        return new(random.Next(-2, 7), random.Next(-2, 7), random.Next(-2, 7),
            random.Next(-2, 7), random.Next(-2, 7), score);
    }

    private static void Require(bool condition, string message)
    {
        _checks++;
        if (!condition) throw new InvalidOperationException(message);
    }

    // Frozen current singleton-object storage, used only for allocation comparison.
    private sealed class LegacyFrontier(TranspositionLabel first)
    {
        // Most retained states have one nondominated label. Keep it in this object:
        // neither an empty tail nor a one-element List/array needs to survive a GC.
        private TranspositionLabel _single = first;
        private List<TranspositionLabel>? _labels;

        public int LabelCount => _labels?.Count ?? 1;

        public bool TryAccept(TranspositionLabel next)
        {
            if (_labels == null)
            {
                if (Dominates(_single, next))
                    return false;
                if (Dominates(next, _single))
                    _single = next;
                else
                    _labels = [_single, next];
                return true;
            }
            foreach (TranspositionLabel current in _labels)
            {
                if (Dominates(current, next))
                    return false;
            }
            _labels.RemoveAll(current => Dominates(next, current));
            _labels.Add(next);
            if (_labels.Count == 1)
            {
                _single = next;
                _labels = null;
            }
            return true;
        }

        private static bool Dominates(TranspositionLabel left, TranspositionLabel right)
            => left.PotionCount <= right.PotionCount
                && left.PotionStrategicCost <= right.PotionStrategicCost
                && left.FutureSoldHp <= right.FutureSoldHp
                && left.CumulativePlayerHpLost <= right.CumulativePlayerHpLost
                && left.ActionCount <= right.ActionCount
                && left.Score >= right.Score;
    }

    // Literal pre-change algorithm, with its own comparator to avoid self-comparison.
    private sealed class Baseline(TranspositionLabel first)
    {
        private readonly List<TranspositionLabel> _labels = [first];
        public int LabelCount => _labels.Count;
        public bool TryAccept(TranspositionLabel next)
        {
            foreach (TranspositionLabel current in _labels)
                if (Dominates(current, next)) return false;
            _labels.RemoveAll(current => Dominates(next, current));
            _labels.Add(next);
            return true;
        }
        private static bool Dominates(TranspositionLabel left, TranspositionLabel right)
            => left.PotionCount <= right.PotionCount
                && left.PotionStrategicCost <= right.PotionStrategicCost
                && left.FutureSoldHp <= right.FutureSoldHp
                && left.CumulativePlayerHpLost <= right.CumulativePlayerHpLost
                && left.ActionCount <= right.ActionCount
                && left.Score >= right.Score;
    }
}

